{
  "name": "zurich-maps",
  "version": "0.1.0",
  "private": true,
  "description": "Historical map explorer (OldMapsOnline-style) in the Canton Z\u00fcrich design system \u2014 Cloudflare Workers site",
  "type": "module",
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "dev": "wrangler dev",
    "preview": "wrangler dev --local",
    "build": "node scripts/validate.mjs",
    "test": "node --test \"tests/*.test.mjs\"",
    "check": "npm run build && npm test && npm run dry-run",
    "dry-run": "wrangler deploy --dry-run --outdir dist",
    "harvest": "node scripts/fetch-records.mjs --out public/data",
    "harvest:offline": "node scripts/fetch-records.mjs --out public/data --offline",
    "verify:endpoints": "node scripts/verify-endpoints.mjs"
  },
  "devDependencies": {
    "wrangler": "^4.151.1"
  }
}
=== wrangler ===
{
  // Cloudflare Workers site: static assets from ./public + a small request
  // handler in src/worker/index.js for /api/* (allowlisted upstream proxy).
  "$schema": "node_modules/wrangler/config-schema.json",
  "name": "zurich-maps",
  "main": "src/worker/index.js",
  "compatibility_date": "2025-08-01",
  "compatibility_flags": ["nodejs_compat"],
  "assets": {
    "directory": "./public",
    "binding": "ASSETS",
    "not_found_handling": "single-page-application",
    // Only /api/* reaches the Worker; everything else is served straight from
    // the asset store (fast path, no Worker invocation, no asset cost).
    "run_worker_first": ["/api/*"]
  },
  "observability": {
    "enabled": true
  },
  "dev": {
    "port": 8787
  }
}
