import { ALLOWLIST, USER_AGENT, VERSION, isAllowed } from './allowlist.js';

/**
 * Request handler for the Zurich maps Workers site.
 *
 * The Worker only answers `/api/*` (see `assets.run_worker_first` in
 * wrangler.jsonc); every other request is served directly from the static asset
 * directory `public/`.
 *
 * Why a proxy at all?
 *  - swisstopo SearchServer (`api3.geo.admin.ch`) sends CORS `*`, but routing it
 *    through the Worker gives us one stable origin, a bounded query and an edge
 *    cache in front of a public service we want to call politely.
 *  - e-rara IIIF images/manifests normally allow CORS; `/api/fetch` is a
 *    *fallback* for clients/networks where the direct call fails. It is limited
 *    to a literal allowlist of hosts, so it cannot be used as an open proxy.
 *
 * No credentials are required or read by this Worker.
 */

function json(body, init = {}) {
  return new Response(JSON.stringify(body, null, 1), {
    ...init,
    headers: { 'content-type': 'application/json; charset=utf-8', ...(init.headers || {}) },
  });
}

async function upstream(url, { accept = '*/*', timeoutMs = 8000 } = {}) {
  return fetch(url, {
    headers: { 'user-agent': USER_AGENT, accept },
    signal: AbortSignal.timeout(timeoutMs),
    redirect: 'follow',
  });
}

/** Read a JSON file that ships with the site through the assets binding. */
async function asset(env, path, request) {
  const url = new URL(request.url);
  url.pathname = path;
  url.search = '';
  return env.ASSETS.fetch(new Request(url.toString(), { method: 'GET' }));
}

async function cachedJson(request, ctx, build, maxAge) {
  const cache = caches.default;
  const cacheKey = new Request(new URL(request.url).toString(), { method: 'GET' });
  const hit = await cache.match(cacheKey);
  if (hit) return hit;
  const body = await build();
  const res = json(body, { headers: { 'cache-control': `public, max-age=${maxAge}` } });
  ctx.waitUntil(cache.put(cacheKey, res.clone()));
  return res;
}

/** GET /api/health — liveness plus the upstreams this Worker may contact. */
function health(request) {
  return json({
    ok: true,
    version: VERSION,
    runtime: 'cloudflare-workers',
    upstreams: ALLOWLIST.map((r) => r.host),
    endpoints: ['/api/health', '/api/records', '/api/layers', '/api/sources', '/api/search/places', '/api/fetch'],
    time: new Date().toISOString(),
  });
}

/** GET /api/search/places?q=&limit= — swisstopo SearchServer (type=locations). */
async function searchPlaces(request, ctx) {
  const url = new URL(request.url);
  const q = (url.searchParams.get('q') || '').trim();
  const limit = Math.min(Math.max(Number(url.searchParams.get('limit') || 8), 1), 20);
  if (q.length < 2 || q.length > 120) {
    return json({ error: 'query_too_short', detail: 'q must be 2..120 characters', results: [] }, { status: 400 });
  }
  return cachedJson(
    request,
    ctx,
    async () => {
      const target = new URL('https://api3.geo.admin.ch/rest/services/api/SearchServer');
      target.searchParams.set('searchText', q);
      target.searchParams.set('type', 'locations');
      target.searchParams.set('sr', '4326'); // WGS84 lon/lat
      target.searchParams.set('limit', String(limit));
      const res = await upstream(target.toString(), { accept: 'application/json' });
      if (!res.ok) {
        return { results: [], upstreamStatus: res.status, note: 'swisstopo SearchServer error' };
      }
      const data = await res.json();
      const results = (data.results || []).map((r) => {
        const a = r.attrs || {};
        const box = (a.geom_st_box2d || 'BOX(0 0,0 0)').match(/BOX\(([-\d.]+) ([-\d.]+),([-\d.]+) ([-\d.]+)\)/);
        return {
          label: String(a.label || '').replace(/<[^>]*>/g, ''),
          origin: a.origin || null,
          lat: typeof a.lat === 'number' ? a.lat : null,
          lon: typeof a.lon === 'number' ? a.lon : null,
          layerBodId: a.layerBodId || null,
          // upstream `zoomlevel` is a bitfield/uint32 for some origins; only pass sane values on
          zoom: Number.isFinite(a.zoomlevel) && a.zoomlevel > 0 && a.zoomlevel <= 20 ? a.zoomlevel : null,
          bbox: box ? { west: Number(box[1]), south: Number(box[2]), east: Number(box[3]), north: Number(box[4]) } : null,
        };
      });
      return { results, source: 'swisstopo SearchServer', attribution: '© swisstopo' };
    },
    300,
  );
}

/** GET /api/fetch?url= — allowlisted pass-through with a 1 h edge cache. */
async function fetchUpstream(request, ctx) {
  const url = new URL(request.url);
  const raw = url.searchParams.get('url');
  if (!raw) return json({ error: 'missing_url' }, { status: 400 });
  let target;
  try {
    target = new URL(raw);
  } catch {
    return json({ error: 'invalid_url' }, { status: 400 });
  }
  if (!isAllowed(target)) {
    return json({ error: 'host_not_allowed', host: target.hostname, allowlist: ALLOWLIST.map((r) => r.host) }, { status: 403 });
  }
  const cache = caches.default;
  const cacheKey = new Request(`${url.origin}/api/fetch?url=${encodeURIComponent(target.toString())}`, { method: 'GET' });
  const hit = await cache.match(cacheKey);
  if (hit) return hit;
  let res;
  try {
    res = await upstream(target.toString(), { accept: url.searchParams.get('accept') || '*/*' });
  } catch (err) {
    return json({ error: 'upstream_unreachable', detail: String(err && err.message) }, { status: 502 });
  }
  if (!res.ok) return json({ error: 'upstream_error', status: res.status }, { status: 502 });
  const type = res.headers.get('content-type') || 'application/octet-stream';
  const out = new Response(res.body, {
    status: 200,
    headers: {
      'content-type': type,
      'cache-control': 'public, max-age=3600',
      'access-control-allow-origin': '*',
      'x-proxied-from': target.hostname,
    },
  });
  ctx.waitUntil(cache.put(cacheKey, out.clone()));
  return out;
}

export default {
  /**
   * @param {Request} request
   * @param {{ ASSETS: { fetch: (r: Request) => Promise<Response> } }} env
   * @param {{ waitUntil: (p: Promise<unknown>) => void }} ctx
   */
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    if (url.pathname.startsWith('/api/')) {
      if (request.method !== 'GET' && request.method !== 'HEAD') {
        return json({ error: 'method_not_allowed' }, { status: 405, headers: { allow: 'GET, HEAD' } });
      }
      try {
        switch (url.pathname) {
          case '/api/health':
            return health(request);
          case '/api/search/places':
            return await searchPlaces(request, ctx);
          case '/api/fetch':
            return await fetchUpstream(request, ctx);
          case '/api/records':
          case '/api/layers':
          case '/api/sources': {
            const path = { '/api/records': '/data/records.json', '/api/layers': '/data/overlays.json', '/api/sources': '/data/sources.json' }[
              url.pathname
            ];
            const res = await asset(env, path, request);
            if (!res.ok) return json({ error: 'asset_missing', path }, { status: 500 });
            return new Response(res.body, {
              status: 200,
              headers: {
                'content-type': 'application/json; charset=utf-8',
                'cache-control': 'public, max-age=300',
                'access-control-allow-origin': '*',
              },
            });
          }
          default:
            return json({ error: 'not_found', path: url.pathname }, { status: 404 });
        }
      } catch (err) {
        return json({ error: 'worker_error', detail: String(err && err.message) }, { status: 500 });
      }
    }

    // Defensive: if run_worker_first is widened, still behave like a static host.
    if (env && env.ASSETS) return env.ASSETS.fetch(request);
    return new Response('Not found', { status: 404, headers: { 'content-type': 'text/plain; charset=utf-8' } });
  },
};

// NOTE: only `default` may be exported from a Workers entrypoint. workerd rejects
// non-function named exports at startup ("Incorrect type for map entry 'VERSION'"
// is the exact failure), so constants stay module-private and are exercised through
// the HTTP surface (see tests/worker.test.mjs → /api/health).
=== allowlist ===
/**
 * Upstream allowlist for the request handler.
 *
 * Kept in its own module because a Worker's entry module may only export a
 * default handler (workerd rejects other top-level exports); everything the
 * tests want to import lives here instead.
 */

export const VERSION = '0.1.0';

/** Hosts the proxy may talk to, and the path prefixes allowed per host. */
export const ALLOWLIST = [
  { host: 'api3.geo.admin.ch', prefixes: ['/rest/services/api/SearchServer'] },
  { host: 'www.e-rara.ch', prefixes: ['/i3f/', '/zuz/oai', '/oai'] },
  { host: 'wmts.geo.admin.ch', prefixes: ['/1.0.0/', '/EPSG/'] },
  { host: 'data.geo.admin.ch', prefixes: ['/'] },
];

export const USER_AGENT =
  'zurich-maps/0.1 (+https://github.com/igor-makarov/maps-n-stuff; historical map explorer)';

/** True when the URL is https, on an allowlisted host and path. */
export function isAllowed(target) {
  if (!(target instanceof URL) || target.protocol !== 'https:') return false;
  const rule = ALLOWLIST.find((r) => r.host === target.hostname);
  if (!rule) return false;
  return rule.prefixes.some((prefix) => target.pathname.startsWith(prefix));
}

/**
 * URL-backed application state + a tiny event bus (coordination/README.md D4).
 *
 *   const store = createStore({ defaults });
 *   store.getState()            -> { q, from, to, provider, type, collection, base, viewport, extents, at, place, lat, lon, zoom, selected, sheet, vv, view, sort, overlay, otime, cmp, cvv, csync }
 *   store.update({ from: 1800 }) -> merge, sync URL, notify subscribers
 *   store.subscribe(fn)          -> fn(state, changedKeys); returns unsubscribe
 *   store.applyUrl()             -> re-read the URL (used by popstate)
 *
 * History: a change to a *deliberate* search/selection key (see
 * HISTORY_PUSH_KEYS) becomes a real history entry, so the browser's back and
 * forward buttons walk the way the user actually explored; continuous changes
 * (panning, zooming, dragging the year control, pinning records) only replace
 * the current entry, so one drag never floods the history. Repeated changes to
 * the same keys inside HISTORY_COALESCE_MS merge into the entry they started,
 * and a query that is still being edited (HISTORY_TEXT_KEYS) stays in its entry
 * even across a longer pause — one “back” undoes the whole typed search.
 * `popstate` re-reads the URL and notifies the modules exactly like an ordinary
 * update does, so every view follows the browser buttons.
 *
 *   const bus = createBus();
 *   bus.on('records:loaded', fn); bus.emit('records:loaded', { records });
 *
 * Everything is defensive: the module must also import cleanly in Node (tests)
 * where `window`/`history`/`location` may not exist.
 */

export const STATE_DEFAULTS = Object.freeze({
  q: '', // free-text filter over title/creator/place
  from: 1500, // publication year range filter
  to: 1900,
  provider: '', // providerId or '' for all
  type: '', // record type or '' for all
  collection: '', // upstream series/collection name or '' for all (facet from the data)
  base: '', // short key of the chosen Grundkarte ('farbe' | 'grau' | 'luftbild'); '' = the default layer
  viewport: '', // '1' = only records inside the current map view
  extents: '', // '1' = draw the documented footprints of the filtered records on the map
  at: '', // "lat,lon" point filter: only records whose documented extent covers this point
  place: '', // selected place label
  lat: 47.3769, // Zürich as the initial view (documented default, not a search result)
  lon: 8.5417,
  zoom: 12,
  selected: '', // record id
  sheet: 1, // 1-based sheet/canvas of the open multi-sheet work (shareable)
  vv: '', // "x,y,w,h" visible region of that sheet in image pixels (shareable; '' = whole sheet)
  view: 'split', // 'split' | 'map' | 'list'
  sort: 'year-asc',
  overlay: '', // swisstopo layer id of the comparison layer
  otime: '', // time value for that layer (YYYYMMDD where the layer is a Zeitreise layer)
  cmp: '', // comma-separated record ids pinned in the comparison list (max 4)
  cvv: '', // cut-outs of the comparison panes: "id@x,y,w,h" pairs, ";"-separated (shareable)
  csync: '1', // '1' = the comparison panes' cut-outs are coupled (the default), '0' = each pane moves alone
});

/** URL parameter names kept short for shareable links. */
export const PARAM = {
  q: 'q',
  from: 'from',
  to: 'to',
  provider: 'p',
  type: 't',
  collection: 'c',
  base: 'base',
  viewport: 'vp',
  extents: 'ex',
  at: 'at',
  place: 'place',
  lat: 'lat',
  lon: 'lon',
  zoom: 'z',
  selected: 'sel',
  sheet: 'sh',
  vv: 'vv',
  view: 'view',
  sort: 'sort',
  overlay: 'ov',
  otime: 'ot',
  cmp: 'cmp',
  cvv: 'cvv',
  csync: 'csync',
};

/**
 * One record id as the data contract writes it (`<providerId>:<recordId>`).
 * Used for the pinned comparison list and for the panes' cut-outs.
 */
const RECORD_ID = /^[a-z0-9][a-z0-9._-]{0,40}:[A-Za-z0-9][A-Za-z0-9._-]{0,80}$/;
/** One `x,y,w,h` region as the viewer writes it; the same shape as `vv`. */
const VIEW_REGION = /^\d{1,6}(?:,\d{1,6}){3}$/;
/** The comparison holds at most four panes, so at most four cut-outs are kept. */
const MAX_COMPARE_VIEWS = 4;

const TYPES = {
  string: ['q', 'provider', 'type', 'collection', 'base', 'viewport', 'extents', 'at', 'place', 'selected', 'view', 'sort', 'overlay', 'otime', 'cmp', 'vv', 'cvv', 'csync'],
  number: ['from', 'to', 'lat', 'lon', 'zoom', 'sheet'],
};

/**
 * Keys whose change is a navigation step the user would want to undo with the
 * browser's back button: a search, a filter, a place or a selected record.
 * Every other key (pan/zoom, slider drags, the sheet or the visible cut-out of a
 * work, the footprint layer, the pinned comparison list, the view and sort
 * choices) only replaces the current entry.
 */
export const HISTORY_PUSH_KEYS = Object.freeze([
  'q',
  'from',
  'to',
  'provider',
  'type',
  'collection',
  'viewport',
  'at',
  'place',
  'selected',
]);

/** Repeated changes to the same keys inside this window replace instead of push. */
export const HISTORY_COALESCE_MS = 900;

/**
 * Keys whose change is *typed text*. A pause inside one query must not cut the
 * search into two history steps: the measured typing pace of a visitor can
 * exceed HISTORY_COALESCE_MS (and a busy main thread does it on its own), and
 * then “back” only undid the last keystroke instead of the whole search. A
 * change to these keys therefore stays in the entry as long as the new text is
 * a continuation of the text of that entry (see `isTypedContinuation`).
 */
export const HISTORY_TEXT_KEYS = Object.freeze(['q']);

function coerce(key, value) {
  if (value === null || value === undefined || value === '') return STATE_DEFAULTS[key];
  if (TYPES.number.includes(key)) {
    const n = Number(value);
    return Number.isFinite(n) ? n : STATE_DEFAULTS[key];
  }
  return String(value);
}

function safeHistory() {
  try {
    if (typeof window === 'undefined') return null;
    return window.history && typeof window.history.replaceState === 'function' ? window.history : null;
  } catch {
    return null;
  }
}

function safeLocation() {
  try {
    if (typeof window === 'undefined') return null;
    return window.location || null;
  } catch {
    return null;
  }
}

function safeWindow() {
  try {
    if (typeof window === 'undefined') return null;
    return window;
  } catch {
    return null;
  }
}

export function readStateFromUrl(search = (safeLocation()?.search ?? ''), defaults = STATE_DEFAULTS) {
  const params = new URLSearchParams(search);
  const state = { ...defaults };
  for (const [key, param] of Object.entries(PARAM)) {
    if (params.has(param)) {
      const raw = params.get(param);
      state[key] = raw === '' ? defaults[key] : coerce(key, raw);
    }
  }
  return sanitise(state);
}

/**
 * Parse the point filter `"lat,lon"`; null when the value is not a real point.
 * Used by the map (crosshair), the result filter and the tests.
 */
export function parsePoint(value) {
  const parts = String(value ?? '').split(',');
  if (parts.length !== 2) return null;
  const lat = Number(parts[0]);
  const lon = Number(parts[1]);
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
  return { lat: Math.max(-85, Math.min(85, lat)), lon: normaliseLon(lon) };
}

/** Canonical `"lat,lon"` for the URL/state; '' when there is no usable point. */
export function sanitisePoint(value) {
  const point = parsePoint(value);
  return point ? `${point.lat.toFixed(4)},${point.lon.toFixed(4)}` : '';
}

/** Wrap a longitude into [-180, 180] without drifting values that are already in range. */
export function normaliseLon(lon) {
  if (!Number.isFinite(lon)) return STATE_DEFAULTS.lon;
  if (lon >= -180 && lon <= 180) return lon;
  const wrapped = ((((lon + 180) % 360) + 360) % 360) - 180;
  return Math.round(wrapped * 1e6) / 1e6;
}

/** Keep numeric state inside sane bounds so a hand-written URL cannot break the UI. */
export function sanitise(state) {
  const out = { ...state };
  out.lat = Math.max(-85, Math.min(85, Number(out.lat) || STATE_DEFAULTS.lat));
  out.lon = normaliseLon(Number(out.lon));
  out.zoom = Math.max(2, Math.min(18, Number(out.zoom) || STATE_DEFAULTS.zoom));
  const from = Number.isFinite(Number(out.from)) ? Number(out.from) : STATE_DEFAULTS.from;
  const to = Number.isFinite(Number(out.to)) ? Number(out.to) : STATE_DEFAULTS.to;
  out.from = Math.min(from, to);
  out.to = Math.max(from, to);
  if (!['split', 'map', 'list'].includes(out.view)) out.view = STATE_DEFAULTS.view;
  if (!['year-asc', 'year-desc', 'title'].includes(out.sort)) out.sort = STATE_DEFAULTS.sort;
  out.viewport = out.viewport === '1' || out.viewport === 'true' ? '1' : '';
  out.extents = out.extents === '1' || out.extents === 'true' ? '1' : '';
  out.at = sanitisePoint(out.at);
  out.q = String(out.q || '').slice(0, 200);
  out.place = String(out.place || '').slice(0, 200);
  // A collection name comes from the data (never invented) and from the URL, so
  // keep it short and printable; an unknown name simply yields no results.
  out.collection = String(out.collection || '').slice(0, 120);
  // Which Grundkarte the map draws (`?base=grau`). The map resolves the key and
  // falls back to the default layer, so only the shape has to be safe here.
  out.base = /^[a-z0-9-]{1,24}$/.test(String(out.base ?? '')) ? String(out.base) : '';
  // Which sheet of a multi-sheet work the detail viewer shows. The real canvas
  // count is only known after the manifest loads, so the hard bound stays wide;
  // detail.js clamps to the actual count and writes the corrected value back.
  out.sheet = Math.max(1, Math.min(999, Math.floor(Number(out.sheet) || 1)));
  // The visible region of the detail viewer, as "x,y,w,h" in image pixels. It is
  // hand-editable like every other parameter, so only the exact shape is kept;
  // the viewer checks it against the real sheet size and drops what does not fit.
  out.vv = /^\d{1,6}(,\d{1,6}){3}$/.test(String(out.vv ?? '')) ? String(out.vv) : '';
  // The compare list is a hand-editable URL value: keep only ids that match the
  // data contract "<providerId>:<record id>" (lower-case provider, safe value
  // characters) and never more than four of them.
  out.cmp = String(out.cmp || '')
    .split(',')
    .map((id) => id.trim())
    .filter((id) => RECORD_ID.test(id))
    .slice(0, MAX_COMPARE_VIEWS)
    .join(',');
  // The cut-outs of the comparison panes, one `id@x,y,w,h` per pane that shows a
  // cut-out instead of the whole sheet. Keyed by record id (the pane order can
  // change), hand-editable like every other parameter, so only pairs matching
  // both contracts survive — capped at the four panes. Each region is checked
  // against the real sheet by the pane that restores it (`parseViewParam`).
  out.cvv = String(out.cvv || '')
    .split(';')
    .map((pair) => pair.trim())
    .filter((pair) => {
      const at = pair.indexOf('@');
      return at > 0 && RECORD_ID.test(pair.slice(0, at)) && VIEW_REGION.test(pair.slice(at + 1));
    })
    .slice(0, MAX_COMPARE_VIEWS)
    .join(';');
  // Whether the comparison panes follow each other. Coupled is the documented
  // default and stays out of the URL; only the visitor's decision to uncouple is
  // shareable (`?csync=0`), so a comparison link reproduces the view it names.
  out.csync = out.csync === '0' || out.csync === 'false' ? '0' : '1';
  return out;
}

export function stateToQuery(state, defaults = STATE_DEFAULTS) {
  const params = new URLSearchParams();
  const current = sanitise({ ...defaults, ...state });
  for (const [key, param] of Object.entries(PARAM)) {
    const value = current[key];
    if (value === defaults[key]) continue;
    if (key === 'lat' || key === 'lon') params.set(param, Number(value).toFixed(4));
    else params.set(param, String(value));
  }
  return params.toString();
}

export function createBus() {
  const listeners = new Map();
  return {
    on(name, fn) {
      if (!listeners.has(name)) listeners.set(name, new Set());
      listeners.get(name).add(fn);
      return () => listeners.get(name)?.delete(fn);
    },
    off(name, fn) {
      listeners.get(name)?.delete(fn);
    },
    emit(name, detail) {
      for (const fn of listeners.get(name) ?? []) {
        try {
          fn(detail);
        } catch (err) {
          // A broken module must not take the app down.
          console.error(`[bus] listener for "${name}" failed`, err);
        }
      }
    },
  };
}

export function createStore({
  initial = {},
  defaults = STATE_DEFAULTS,
  history = safeHistory(),
  location = safeLocation(),
  window: win = safeWindow(),
  now = () => Date.now(), // injectable clock: the coalescing window is testable
} = {}) {
  let state = sanitise({ ...defaults, ...initial, ...readStateFromUrl(location?.search ?? '', defaults) });
  const subscribers = new Set();
  let urlSync = Boolean(history && location);
  // Which URL the browser is on right now. Comparing against it keeps us from
  // writing an entry twice and from turning a no-op into a history step.
  let lastUrl = urlOf();
  let lastPushSignature = '';
  let lastPushAt = 0;
  let suppressPushUntil = 0;
  // The query text of the history entry we are on: a later keystroke that still
  // continues it is the same gesture, however long the pause in between was.
  let entryQ = String(state.q ?? '');
  // Flipped by the first pointer/key event; until then every URL write replaces.
  let userActed = false;
  const markUserAction = () => {
    userActed = true;
  };

  function urlOf() {
    if (!location) return '';
    return `${location.pathname || '/'}${location.search || ''}${location.hash || ''}`;
  }

  function notify(changedKeys) {
    for (const fn of subscribers) {
      try {
        fn(state, changedKeys);
      } catch (err) {
        console.error('[store] subscriber failed', err);
      }
    }
  }

  const signatureOf = (changedKeys) => [...changedKeys].sort().join(',');
  /**
   * Should this change open a new history entry? Only deliberate state changes
   * do, and never twice in a row for the same set of keys inside
   * HISTORY_COALESCE_MS — that is what keeps typing in the filter box from
   * leaving one entry per keystroke.
   *
   * Two guard rails:
   *  - `userActed` — the app repairs its own initial state after the data
   *    arrives (the year range is clamped to the years that exist), and that
   *    repair must land in the entry the visitor arrived on, not on top of it;
   *    otherwise the first press of “back” would stay inside the app.
   *  - `suppressPushUntil` — the same for writes right after a popstate.
   */
  /**
   * Is this change a continuation of the text in the current history entry?
   * Only for the typed keys, only for the same key set as the entry's push, and
   * only while the text really continues it in either direction: typing and
   * backspacing stay one step, a query rewritten from scratch (or one that
   * starts from an empty box) is a step of its own.
   */
  function isTypedContinuation(changedKeys) {
    if (changedKeys.length === 0) return false;
    if (!changedKeys.every((key) => HISTORY_TEXT_KEYS.includes(key))) return false;
    const before = entryQ;
    const after = String(state.q ?? '');
    if (before === '' || after === '') return false;
    return before.startsWith(after) || after.startsWith(before);
  }

  function shouldPush(changedKeys, stamp) {
    if (!userActed) return false;
    if (stamp < suppressPushUntil) return false;
    if (!changedKeys.some((key) => HISTORY_PUSH_KEYS.includes(key))) return false;
    const signature = signatureOf(changedKeys);
    if (signature !== lastPushSignature) return true;
    if (stamp - lastPushAt < HISTORY_COALESCE_MS) return false;
    // Same control, but the visitor kept editing the same query: still one step.
    return !isTypedContinuation(changedKeys);
  }

  function syncUrl(mode = 'auto', changedKeys = []) {
    if (!urlSync || !history || !location) return;
    const query = stateToQuery(state, defaults);
    const next = `${location.pathname || '/'}${query ? `?${query}` : ''}${location.hash || ''}`;
    if (next === lastUrl) return;
    const stamp = now();
    const push = mode === 'push' || (mode === 'auto' && shouldPush(changedKeys, stamp));
    try {
      if (push) history.pushState({ ...state }, '', next);
      else history.replaceState({ ...state }, '', next);
      // A gesture stays the same gesture as long as changes keep arriving: the
      // window is measured from the *last* change of this key set, not from the
      // entry it opened. Otherwise a long drag or a long word would push again
      // in the middle of the gesture.
      lastPushSignature = signatureOf(changedKeys);
      lastPushAt = stamp;
      entryQ = String(state.q ?? '');
      lastUrl = next;
    } catch {
      urlSync = false; // sandboxed iframe or file:// – keep working without URL sync
    }
  }

  function update(patch, { silent = false, history: mode = 'auto' } = {}) {
    const changed = [];
    const next = { ...state };
    for (const [key, value] of Object.entries(patch)) {
      if (!(key in defaults)) continue;
      const coerced = coerce(key, value);
      if (next[key] !== coerced) {
        next[key] = coerced;
        changed.push(key);
      }
    }
    state = sanitise(next);
    if (changed.length === 0) return state;
    syncUrl(mode, changed);
    if (!silent) notify(changed);
    return state;
  }

  /**
   * Read the state back out of the URL the browser just moved us to. Returns
   * the list of keys that really changed, so the caller can tell a real
   * navigation from a hash-only popstate. Modules need no extra wiring: they
   * receive the same `(state, changedKeys)` notification as from `update()`.
   */
  function applyUrl() {
    if (!location) return [];
    const parsed = readStateFromUrl(location.search || '', defaults);
    const changed = Object.keys(defaults).filter((key) => state[key] !== parsed[key]);
    lastUrl = urlOf();
    lastPushSignature = '';
    // The entry we just moved to owns its own query text; typing on from here
    // continues *that* search, not the one we left.
    entryQ = String(parsed.q ?? '');
    // A view that writes its clamped state back (for example a sheet number)
    // must not turn the entry we just navigated to into a second entry.
    suppressPushUntil = now() + HISTORY_COALESCE_MS;
    if (changed.length === 0) return [];
    state = parsed;
    notify(changed);
    return changed;
  }

  if (urlSync && typeof win?.addEventListener === 'function') {
    win.addEventListener('popstate', () => {
      applyUrl();
    });
    // The first real interaction separates “the app fixing up its own start-up
    // state” (replace) from what the visitor asked for (push). The `click`
    // listener is captured so that it is seen before the clicked control's own
    // handler, and a plain `click` event counts too — an activation that never
    // saw a pointer or a key (screen reader, `el.click()`) is still a user
    // decision.
    win.addEventListener('click', markUserAction, { capture: true, passive: true });
    for (const type of ['pointerdown', 'keydown', 'touchstart']) {
      win.addEventListener(type, markUserAction, { passive: true });
    }
  }

  return {
    getState: () => state,
    update,
    subscribe(fn) {
      subscribers.add(fn);
      return () => subscribers.delete(fn);
    },
    /** Used by tests and by the "reset" action. */
    replace(next, options) {
      return update({ ...defaults, ...next }, options);
    },
    /** Back/forward handling and the tests call this. */
    applyUrl,
    setUrlSync(enabled) {
      urlSync = Boolean(enabled);
    },
  };
}

#!/usr/bin/env node
/**
 * Build/validation step (`npm run build`, also used as the Cloudflare build
 * command): checks that the Workers site is complete and internally consistent
 * *without* contacting the network or needing Cloudflare credentials.
 *
 *   - wrangler.jsonc parses (JSONC comments stripped) and has main + assets
 *   - every asset referenced by public/index.html exists
 *   - all ES modules parse (node --check) and import the contracted helpers
 *   - public/data/{records,sources,overlays}.json parse and pass the D4 schema
 *   - the worker exposes default.fetch and an allowlist
 */
import { readFile, access } from 'node:fs/promises';
import { execFile } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';
import path from 'node:path';

const run = promisify(execFile);
const root = fileURLToPath(new URL('..', import.meta.url));
const problems = [];
const notes = [];

const fail = (message) => problems.push(message);
const abs = (...parts) => path.join(root, ...parts);

/** Strip // and /* *\/ comments plus trailing commas from JSONC. */
export function parseJsonc(text) {
  let out = '';
  let inString = false;
  let inLine = false;
  let inBlock = false;
  for (let i = 0; i < text.length; i += 1) {
    const c = text[i];
    const next = text[i + 1];
    if (inLine) {
      if (c === '\n') {
        inLine = false;
        out += c;
      }
      continue;
    }
    if (inBlock) {
      if (c === '*' && next === '/') {
        inBlock = false;
        i += 1;
      }
      continue;
    }
    if (inString) {
      out += c;
      if (c === '\\') {
        out += next ?? '';
        i += 1;
      } else if (c === '"') inString = false;
      continue;
    }
    if (c === '"') {
      inString = true;
      out += c;
      continue;
    }
    if (c === '/' && next === '/') {
      inLine = true;
      i += 1;
      continue;
    }
    if (c === '/' && next === '*') {
      inBlock = true;
      i += 1;
      continue;
    }
    out += c;
  }
  return JSON.parse(out.replace(/,\s*([}\]])/g, '$1'));
}

async function checkWrangler() {
  const raw = await readFile(abs('wrangler.jsonc'), 'utf8');
  const config = parseJsonc(raw);
  if (!config.main) fail('wrangler.jsonc: missing "main"');
  if (!config.assets?.directory) fail('wrangler.jsonc: missing assets.directory');
  if (config.assets && !config.assets.binding) notes.push('wrangler.jsonc: assets.binding not set (worker cannot read data files)');
  if (!config.compatibility_date) fail('wrangler.jsonc: missing compatibility_date');
  const mainPath = abs(config.main);
  await access(mainPath).catch(() => fail(`wrangler.jsonc: main "${config.main}" does not exist`));
  await access(abs(config.assets.directory)).catch(() => fail(`wrangler.jsonc: assets.directory "${config.assets.directory}" does not exist`));
  notes.push(`wrangler.jsonc: name=${config.name} assets=${config.assets.directory} main=${config.main}`);
  return config;
}

async function checkHtmlAssets() {
  const html = await readFile(abs('public/index.html'), 'utf8');
  const refs = [...html.matchAll(/(?:src|href)="(\/[^"#?]+)"/g)].map((m) => m[1]);
  const modules = [...html.matchAll(/<script[^>]+src="(\/[^"]+)"/g)].map((m) => m[1]);
  if (modules.length === 0) fail('public/index.html: no module script found');
  for (const ref of new Set([...refs, ...modules])) {
    if (ref.endsWith('/') || ref.startsWith('/api/')) continue;
    await access(abs('public', ref.replace(/^\//, ''))).catch(() => fail(`public/index.html references missing asset ${ref}`));
  }
  for (const id of ['place-search', 'place-input', 'place-suggestions', 'result-list', 'results-state', 'map', 'detail', 'detail-body', 'scrim', 'year-from', 'year-to', 'overlay-select', 'text-filter', 'compare-panel', 'compare-list', 'compare-view', 'compare-view-body']) {
    if (!html.includes(`id="${id}"`)) fail(`public/index.html: missing element #${id} (contracted UI hook)`);
  }
  notes.push(`public/index.html: ${new Set(refs).size} asset references, all present`);
}

async function checkModules() {
  const modules = ['public/app/main.js', 'public/app/store.js', 'public/app/dom.js', 'public/app/records.js', 'public/app/map.js', 'public/app/search.js', 'public/app/results.js', 'public/app/detail.js', 'public/app/compare.js', 'src/worker/index.js'];
  for (const file of modules) {
    try {
      await run(process.execPath, ['--check', abs(file)]);
    } catch (err) {
      fail(`${file}: syntax error – ${String(err.stderr || err.message).split('\n')[0]}`);
    }
  }
  const worker = await readFile(abs('src/worker/index.js'), 'utf8');
  if (!/export default/.test(worker)) fail('src/worker/index.js: no default export');
  // Workers module format: every *named* export of the entry module is treated
  // as an extra service entrypoint. A non-function export (e.g. `export const
  // VERSION = '1'`) makes `wrangler dev`/deploy fail with
  //   "Incorrect type for map entry 'VERSION': … not of type 'function or
  //   ExportedHandler'"
  // Pure helpers therefore belong in src/worker/allowlist.js (or another module).
  for (const match of worker.matchAll(/^\s*export\s+(?!default\b)(.{0,40})/gm)) {
    fail(
      `src/worker/index.js: named export "${match[1].trim()}" is not allowed in the Workers entry module – ` +
        'move helpers to src/worker/allowlist.js (workerd treats named exports as service entrypoints)',
    );
  }
  for (const endpoint of ['/api/health', '/api/records', '/api/layers', '/api/sources', '/api/search/places', '/api/fetch']) {
    if (!worker.includes(endpoint)) fail(`src/worker/index.js: endpoint ${endpoint} missing`);
  }
  const main = await readFile(abs('public/app/main.js'), 'utf8');
  for (const moduleName of ['map.js', 'search.js', 'results.js', 'detail.js', 'compare.js']) {
    if (!main.includes(moduleName)) fail(`public/app/main.js: optional module ${moduleName} not wired`);
  }
  notes.push(`modules: ${modules.length} checked, optional modules wired`);
}

async function checkData() {
  const records = JSON.parse(await readFile(abs('public/data/records.json'), 'utf8'));
  const sources = JSON.parse(await readFile(abs('public/data/sources.json'), 'utf8'));
  const overlays = JSON.parse(await readFile(abs('public/data/overlays.json'), 'utf8'));
  if (!Array.isArray(records.records) || records.records.length === 0) fail('records.json: no records');
  if (!Array.isArray(sources.providers) || sources.providers.length === 0) fail('sources.json: no providers');
  if (!Array.isArray(overlays.overlays) || overlays.overlays.length === 0) fail('overlays.json: no overlays');
  const ids = new Set();
  let depicted = 0;
  const providerIds = new Set(sources.providers.map((p) => p.id));
  for (const record of records.records ?? []) {
    for (const field of ['id', 'title', 'providerId', 'institution', 'rights', 'recordUrl', 'yearStart', 'yearEnd', 'thumbnail']) {
      if (record[field] === undefined || record[field] === null || record[field] === '') fail(`records.json: ${record.id ?? '?'} missing ${field}`);
    }
    if (ids.has(record.id)) fail(`records.json: duplicate id ${record.id}`);
    ids.add(record.id);
    if (!providerIds.has(record.providerId)) fail(`records.json: ${record.id} uses unknown provider ${record.providerId}`);
    if (record.recordUrl && !record.recordUrl.startsWith('https://')) fail(`records.json: ${record.id} recordUrl is not https`);
    if ((record.yearStart ?? 0) > (record.yearEnd ?? 0)) fail(`records.json: ${record.id} yearStart > yearEnd`);
    // Depicted dates are only allowed as a pair with the upstream evidence that
    // states them (the harvest writes `depictedSource` verbatim), and the map
    // cannot show a period that starts after it was printed.
    const hasDepicted = record.depictedYearStart != null || record.depictedYearEnd != null;
    if (hasDepicted) {
      if (record.depictedYearStart == null || record.depictedYearEnd == null) {
        fail(`records.json: ${record.id} states only half a depicted period`);
      } else {
        if (record.depictedYearStart > record.depictedYearEnd) fail(`records.json: ${record.id} depicted start > end`);
        if (record.depictedYearEnd > (record.yearEnd ?? record.yearStart)) {
          fail(`records.json: ${record.id} depicted period ends after the publication year`);
        }
      }
      if (typeof record.depictedSource !== 'string' || record.depictedSource.length < 10) {
        fail(`records.json: ${record.id} has a depicted period but no depictedSource evidence`);
      }
      depicted += 1;
    }
    if (record.extent) {
      const { west, east, south, north } = record.extent;
      if (!(west < east && south < north)) fail(`records.json: ${record.id} invalid bbox`);
    }
  }
  notes.push(
    `data: ${records.records.length} records, ${sources.providers.length} providers, ${overlays.overlays.length} overlays, ${depicted} with a documented depicted period (generated ${records.generatedAt ?? '?'})`,
  );
}

try {
  await checkWrangler();
  await checkHtmlAssets();
  await checkModules();
  await checkData();
} catch (err) {
  fail(`validation crashed: ${err?.message || err}`);
}

if (problems.length > 0) {
  console.error(`✗ build validation failed (${problems.length} problem(s))`);
  for (const problem of problems) console.error(`  - ${problem}`);
  process.exit(1);
}
console.log('✓ workers site validated');
for (const note of notes) console.log(`  · ${note}`);

#!/usr/bin/env node
/**
 * Reproduce the seed dataset from primary sources.
 *
 * Sources (retrieved 2026-10-18):
 *  - e-rara OAI-PMH  https://www.e-rara.ch/oai  (set `zuz` = ZB Zürich, `landkarten`)
 *  - e-rara IIIF Presentation 2.0 manifests with verbatim metadata + stated map bbox
 *  - swisstopo WMTS capabilities https://wmts.geo.admin.ch/EPSG/3857/1.0.0/WMTSCapabilities.xml
 *
 * No upstream metadata is invented: titles/imprints/creators/institutions/rights are
 * copied from the IIIF manifest (which mirrors the catalogue record), and geographic
 * extents are parsed from the upstream "Kartendaten" statement. swisstopo overlay
 * editions come from the WMTS Time dimension.
 *
 * Usage:
 *   node scripts/fetch-records.mjs --out public/data      # refresh from the network
 *   node scripts/fetch-records.mjs --offline              # replay the .cache/ responses
 *   node scripts/fetch-records.mjs --out /tmp/out --no-write
 *
 * The script is deliberately dependency-free and polite: max 3 concurrent requests,
 * a short pause between manifest requests, a descriptive User-Agent, and an on-disk
 * response cache (`.cache/fetch/`, git-ignored) so repeated runs do not hammer the
 * upstreams. `--offline` never opens a network connection.
 */
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { createHash } from 'node:crypto';
import { pathToFileURL } from 'node:url';

const UA = 'Kartenzeit/1.0 (Canton-Zurich design study; contact: project maintainers)';
const args = process.argv.slice(2);
const outDir = resolve(getArg('--out') || 'public/data');
const writeOutput = !args.includes('--no-write');
const OFFLINE = args.includes('--offline');
const RETRIEVED = '2026-10-19';
const CACHE_DIR = new URL('../.cache/fetch/', import.meta.url);

function getArg(name) {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : null;
}

function cacheFile(url, as) {
  const hash = createHash('sha1').update(url).digest('hex').slice(0, 20);
  return new URL(`./${hash}.${as === 'json' ? 'json' : 'txt'}`, CACHE_DIR);
}

async function get(url, { as = 'text', timeout = 25000 } = {}) {
  const file = cacheFile(url, as);
  if (OFFLINE) {
    const cached = await readFile(file, 'utf8');
    return as === 'json' ? JSON.parse(cached) : cached;
  }
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), timeout);
  try {
    const res = await fetch(url, {
      headers: { 'user-agent': UA, accept: as === 'json' ? 'application/json' : '*/*' },
      signal: ctrl.signal,
    });
    if (!res.ok) throw new Error(`${res.status} ${url}`);
    const body = as === 'json' ? await res.json() : await res.text();
    await mkdir(CACHE_DIR, { recursive: true });
    await writeFile(file, as === 'json' ? JSON.stringify(body) : body);
    return body;
  } finally {
    clearTimeout(timer);
  }
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function decode(s) {
  return String(s || '')
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
    .replace(/&#(\d+);/g, (_, num) => String.fromCodePoint(Number(num)))
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .trim();
}

function first(xml, tag) {
  const m = xml.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`));
  return m ? decode(m[1]) : null;
}

function all(xml, tag) {
  return [...xml.matchAll(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`, 'g'))].map((m) => decode(m[1]));
}

/** e-rara OAI-PMH pages for one set; returns raw <record> strings. */
async function oaiRecords(set, maxPages) {
  const records = [];
  let token = null;
  for (let page = 0; page < maxPages; page++) {
    const url = token
      ? `https://www.e-rara.ch/oai?verb=ListRecords&resumptionToken=${encodeURIComponent(token)}`
      : `https://www.e-rara.ch/oai?verb=ListRecords&metadataPrefix=oai_dc&set=${encodeURIComponent(set)}`;
    const xml = await get(url);
    records.push(...all(xml, 'record'));
    const m = xml.match(/<resumptionToken[^>]*>([^<]+)<\/resumptionToken>/);
    token = m ? m[1] : null;
    if (!token) break;
    await sleep(120);
  }
  return records;
}

function parseOai(record) {
  const setSpecs = all(record, 'setSpec');
  const types = all(record, 'dc:type');
  const title = all(record, 'dc:title')[0] || '';
  const dates = all(record, 'dc:date');
  const ids = all(record, 'dc:identifier');
  const doi = ids.find((i) => i.startsWith('https://www.e-rara.ch/doi/')) || null;
  const oai = first(record, 'identifier');
  const titleId = (oai || '').split(':').pop();

/**
 * Bootstrap for Kartenzeit. Loads the data, wires the optional UI modules and
 * degrades gracefully when one of them is missing (coordination D4).
 */

import { createBus, createStore } from './store.js';
import { el, qs, formatYearRange, setStatus, copyText } from './dom.js';
import { loadOverlays, loadRecords, loadSources, yearBounds } from './records.js';

const bus = createBus();
const store = createStore();

const ctx = {
  store,
  bus,
  dom: { el, qs },
  data: {
    records: [],
    sources: [],
    overlays: [],
    recordIndex: new Map(),
    years: { min: 1500, max: 1900 },
    loadErrors: [],
  },
  moduleErrors: [],
};

const optionalModules = [
  ['map', './map.js'],
  ['search', './search.js'],
  ['results', './results.js'],
  ['detail', './detail.js'],
  ['compare', './compare.js'],
];

async function initModules() {
  const loaded = [];
  ctx.moduleApis = {};
  for (const [name, specifier] of optionalModules) {
    try {
      const module = await import(specifier);
      if (typeof module.init === 'function') {
        // Modules may return a small API (used by the browser checks); the shell
        // only stores it, it never reaches into another module's internals.
        ctx.moduleApis[name] = await module.init(ctx);
        loaded.push(name);
      }
    } catch (err) {
      // A missing/failing module must not stop the rest of the app — but it must
      // not be invisible either: report it in the UI (see reportModuleProblems).
      console.warn(`[kartenzeit] module "${name}" not available`, err);
      ctx.moduleErrors.push({ name, message: err?.message || String(err) });
    }
  }
  ctx.modules = loaded;
  bus.emit('app:ready', ctx);
}

/**
 * A failing optional module leaves a visible, honest notice instead of a
 * silently dead control (a broken search.js once threw during import and the
 * module simply disappeared). `document.documentElement.dataset.moduleErrors`
 * exposes the same fact to tests and monitoring.
 */
function reportModuleProblems() {
  const problems = ctx.moduleErrors ?? [];
  document.documentElement.dataset.moduleErrors = problems.map((p) => p.name).join(',');
  if (problems.length === 0) return;
  const host = qs('#app-notices');
  if (!host) return;
  host.hidden = false;
  host.className = 'zh-state zh-state--error';
  host.replaceChildren(
    el('span', { class: 'zh-state__title', text: 'Eine Teilfunktion ist derzeit nicht verfügbar.' }),
    el('span', {
      text:
        `Betroffen: ${problems.map((p) => p.name).join(', ')}. ` +
        'Die übrigen Funktionen laufen weiter. Bitte die Seite neu laden; bleibt es dabei, ist ein Fehler im Client gemeldet.',
    }),
  );
}

/**
 * “Suchlink kopieren”: the whole filter/selection state is already in the URL
 * (see store.js), so sharing a search only needs a way to copy it — useful on a
 * phone, where selecting the address bar by hand is painful.
 */
function wirePermalinkCopy() {
  const button = qs('#permalink-copy');
  const status = qs('#permalink-status');
  if (!button) return;
  button.addEventListener('click', async () => {
    const ok = await copyText(window.location.href);
    setStatus(
      status,
      ok
        ? 'Link zu dieser Ansicht kopiert — Filter, Kartenausschnitt und Auswahl sind darin enthalten.'
        : 'Kopieren nicht möglich. Bitte die Adresse aus der Adresszeile übernehmen — sie enthält denselben Zustand.',
      ok ? 'success' : 'warn',
    );
  });
}

function renderIntro() {
  // The count appears in the lead paragraph and again in “Über das Projekt”,
  // where the full wording stands (the lead is clamped on small screens).
  const count = String(ctx.data.records.length);
  for (const node of document.querySelectorAll('#intro-count, [data-record-count]')) {
    node.textContent = count;
  }

  // Facts strip: only statements the data actually supports. Two hosts exist:
  // the hero band (hidden below 600 px) and the “Über das Projekt” card, which
  // takes the figures over on phones so the map stays within reach.
  const factsItems = (() => {
    const providersInUse = new Set(ctx.data.records.map((r) => r.providerId));
    const withManifest = ctx.data.records.filter((r) => r.iiifManifest).length;
    return [
      ['Digitalisate', `${ctx.data.records.length}`],
      ['Zeitraum', `${ctx.data.years.min}–${ctx.data.years.max}`],
      ['Anbieter', `${providersInUse.size}`],
      ['IIIF-Bildservice', `${withManifest}`],
    ].map(([term, value]) =>
      el('li', {}, [el('span', { class: 'zh-facts__value', text: value }), el('span', { class: 'zh-facts__term', text: term })]),
    );
  })();
  const collections = new Set(ctx.data.records.map((r) => r.collection).filter(Boolean)).size;
  const withExtent = ctx.data.records.filter((r) => r.extent).length;
  const factsTitle = `${collections} Sammlungen · ${withExtent} von ${ctx.data.records.length} Datensätzen mit Kartenausschnitt · ${ctx.data.overlays.length} georeferenzierte swisstopo-Kartenwerke`;
  for (const facts of document.querySelectorAll('#intro-facts, #about-facts')) {
    facts.replaceChildren(...factsItems.map((item) => item.cloneNode(true)));
    // The compact strip on a phone carries the same honest detail as a title.
    facts.title = factsTitle;
  }

  const tagList = qs('#intro-tags');
  if (tagList) {
    const providersInUse = new Set(ctx.data.records.map((r) => r.providerId));
    tagList.replaceChildren(
      ...ctx.data.sources
        .filter((source) => providersInUse.has(source.id))
        .map((source) =>
          el('li', {}, [el('span', { class: 'zh-tag zh-tag--blue', text: source.name?.split('–')[0]?.trim() || source.id })]),
        ),
      el('li', {}, [el('span', { class: 'zh-tag zh-tag--turquoise', text: `${ctx.data.overlays.length} swisstopo-Kartenwerke` })]),
    );
  }
  const sourceList = qs('#source-list');
  if (sourceList) {
    const entries = [];
    for (const source of ctx.data.sources) {
      entries.push(el('dt', { text: source.name || source.id }));
      entries.push(
        el('dd', {}, [
          source.attribution ? el('span', { text: `${source.attribution}. ` }) : null,
          source.rights ? el('span', { text: `${source.rights} ` }) : null,
          source.homepage ? el('a', { href: source.homepage, rel: 'noopener', text: source.homepage.replace(/^https?:\/\//, '') }) : null,
          source.api?.oai ? el('div', { html: `<small>OAI-PMH: <code>${source.api.oai.split(' ')[0]}</code></small>` }) : null,
        ]),
      );
    }
    sourceList.replaceChildren(...entries);
  }
  // Honest provenance: the page says when the seed was last harvested. The
  // timestamp comes from records.json, not from the visitor's clock.
  const stand = qs('#data-stand');
  if (stand && ctx.data.generatedAt) {
    const [year, month, day] = String(ctx.data.generatedAt).slice(0, 10).split('-');
    if (year && month && day) {
      stand.textContent = `Datenstand: ${day}.${month}.${year} · Herkunft und Rechte je Anbieter siehe Quellenregister (/data/sources.json).`;
      stand.hidden = false;
    }
  }
  const state = qs('#results-state');
  if (state && ctx.data.loadErrors.length > 0) {
    state.hidden = false;
    state.className = 'zh-state zh-state--error';
    state.textContent = `Datenprüfung: ${ctx.data.loadErrors.length} Feld(er) unvollständig – bitte Quellenregister prüfen.`;
  }
}

/** View switch (shell-owned): list only, map only or both. */
function initViewSwitch() {
  const buttons = [...document.querySelectorAll('[data-view]')];
  if (buttons.length === 0) return;

  const apply = (view) => {
    document.body.classList.remove('app-view--split', 'app-view--list', 'app-view--map');
    document.body.classList.add(`app-view--${view}`);
    for (const button of buttons) button.setAttribute('aria-pressed', String(button.dataset.view === view));
  };

  for (const button of buttons) {
    button.addEventListener('click', () => ctx.store.update({ view: button.dataset.view }));
  }
  ctx.store.subscribe((next, changed) => {
    if (changed.includes('view')) apply(next.view);
  });
  apply(ctx.store.getState().view);
}

/**
 * “Nach oben” (cantonal `mdl-back2top`): the button only exists once the page is
 * scrolled, and it moves focus to the content start after scrolling, so a
 * keyboard user is not stranded on a control that has just been hidden.
 */
function wireBackToTop() {
  const button = qs('#back-to-top');
  if (!button) return;
  const visible = () => window.scrollY >= Math.max(600, window.innerHeight * 1.5);
  const sync = () => {
    button.hidden = !visible();
  };
  window.addEventListener('scroll', sync, { passive: true });
  window.addEventListener('resize', sync, { passive: true });
  button.addEventListener('click', () => {
    const reduceMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches;
    window.scrollTo({ top: 0, behavior: reduceMotion ? 'auto' : 'smooth' });
    const main = qs('#main');
    if (main && typeof main.focus === 'function') main.focus({ preventScroll: true });
    sync();
  });
  sync();
}

/**
 * The results area starts with a visible loading state (see index.html): the
 * seed is one JSON file, and on a slow connection the difference between “the
 * app is working” and a blank panel. Both paths below end it — the data, or the
 * failure — so the page never keeps claiming to load.
 */
function finishLoading() {
  const loading = qs('#results-loading');
  if (loading) loading.hidden = true;
  const list = qs('#result-list');
  if (list) list.setAttribute('aria-busy', 'false');
}

async function main() {
  document.documentElement.dataset.app = 'kartenzeit';
  initViewSwitch();

  // Data first: every module can rely on ctx.data being populated.
  try {
    const [{ records, errors, generatedAt }, sources, overlays] = await Promise.all([loadRecords(), loadSources(), loadOverlays()]);
    ctx.data.records = records;
    ctx.data.sources = sources.providers;
    ctx.data.overlays = overlays.overlays;
    ctx.data.recordIndex = new Map(records.map((r) => [r.id, r]));
    ctx.data.years = yearBounds(records);
    ctx.data.generatedAt = generatedAt;
    ctx.data.loadErrors = errors;
    finishLoading();
    bus.emit('records:loaded', { records, sources: sources.providers, overlays: overlays.overlays });
  } catch (err) {
    // The raw message (a browser string like “Failed to fetch”) stays in the
    // console and in the title attribute; the visible text is plain German.
    console.error('[kartenzeit] data load failed', err);
    finishLoading();
    const count = qs('#result-count');
    if (count) count.textContent = 'Bestand nicht geladen';
    const state = qs('#results-state') || qs('#map-fallback');
    if (state) {
      state.hidden = false;
      state.className = 'zh-state zh-state--error';
      state.title = String(err?.message || err);
      state.replaceChildren(
        el('span', { class: 'zh-state__title', text: 'Die Datensätze konnten nicht geladen werden.' }),
        el('span', { text: 'Bitte die Seite neu laden. Die Rohdaten liegen unter /data/records.json; den technischen Grund nennt die Browser-Konsole.' }),
      );
    }
    bus.emit('records:error', { error: err });
    return; // still initialise modules so the map/search part is usable
  }

  renderIntro();
  wirePermalinkCopy();
  wireBackToTop();
  await initModules();
  reportModuleProblems();

  // Diagnostics for the console and for curious users of the API.
  console.info(
    `[kartenzeit] ${ctx.modules?.length ?? 0} Modul(e): ${(ctx.modules ?? []).join(', ')} · ` +
      `${ctx.data.records.length} Datensätze · ${ctx.data.overlays.length} Kartenwerke (${ctx.data.generatedAt ?? 'ohne Datum'})`,
  );
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    main().catch((err) => console.error('[kartenzeit] startup failed', err));
  });
} else {
  main().catch((err) => console.error('[kartenzeit] startup failed', err));
}

export { bus, store, ctx, main };

